def create_effect(effect_type, **options):
    """Create one of the frozen v1 semantic effect classes."""
    try:
        effect_class = EFFECT_CLASSES[effect_type]
    except KeyError as error:
        raise EffectError(f"Unknown effect type: {effect_type}") from error
    return effect_class(**options)

